import{_ as t,a as o,b as e,c as i,d as r}from"./chunks/device-tablet-landscape.D4FvTdpl.js";import{_ as s,o as p,c,a2 as n}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"デバイスごとの表示","description":"同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。","frontmatter":{"description":"同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。"},"headers":[],"relativePath":"ja/guide/devices.md","filePath":"ja/guide/devices.md","lastUpdated":1794776981000}'),l={name:"ja/guide/devices.md"};function d(g,a,h,m,f,u){return p(),c("div",null,[...a[0]||(a[0]=[n('<h1 id="デバイスごとの表示" tabindex="-1">デバイスごとの表示 <a class="header-anchor" href="#デバイスごとの表示" aria-label="Permalink to &quot;デバイスごとの表示&quot;">​</a></h1><p>同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。</p><h2 id="pc-横向き-—-1440-px" tabindex="-1">PC 横向き — 1440 px <a class="header-anchor" href="#pc-横向き-—-1440-px" aria-label="Permalink to &quot;PC 横向き — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="幅 1440 px のウィンドウ：左にライブラリのサイドバー、中央に 3 つの比較ペイン、右にノート列"><figcaption>1440 px：左がサイドバー、中央が 3 言語の並列、右がノート列。</figcaption></figure><p>1440 px ではサイドバー（約 240 px）、比較ステージ、ノート列が同時に見えます。3 言語のペインが横に並ぶので、ひと続きのやり取りがスクロールなしで収まります。幅が 1180 px を超えるとノート列は既定で開き、仕切りをドラッグすれば広げられ、<strong>ノート</strong>（<code>N</code>）で閉じられます。</p><h2 id="pc-縦向き-—-900-×-1200" tabindex="-1">PC 縦向き — 900 × 1200 <a class="header-anchor" href="#pc-縦向き-—-900-×-1200" aria-label="Permalink to &quot;PC 縦向き — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="900 × 1200 の狭いウィンドウ：ライブラリがドロワーに畳まれ、比較ペインが縦に積まれる"><figcaption>900 × 1200：サイドバーはドロワーへ、比較は 1 列、ノート列は既定で閉じています。</figcaption></figure><p>900 px になると狭い画面モードに入ります。ライブラリは ☰ ボタンの後ろのドロワーに畳まれ、比較ペインは 1 列に縦積みになり、ノート列は既定で閉じます（<strong>ノート</strong> で呼び戻せます）。ツールバーのグループは文字ラベルを落とし、入りきらない操作は <strong>More</strong> に移ります。</p><h2 id="スマートフォン縦向き-—-390-×-844" tabindex="-1">スマートフォン縦向き — 390 × 844 <a class="header-anchor" href="#スマートフォン縦向き-—-390-×-844" aria-label="Permalink to &quot;スマートフォン縦向き — 390 × 844&quot;">​</a></h2><figure class="shot"><img src="'+e+'" alt="390 × 844 のスマートフォン画面：比較は 1 列で、言語チップと複数行に折り返したツールバー"><figcaption>390 × 844：比較は 1 列。**言語**チップで JA / EN / ZH を切り替え、ツールバーは複数行に折り返します。</figcaption></figure><p>390 px のスマートフォンでは、トップバーが 3 行に折り返します。ナビゲーションとページ操作、次に UI 言語と書き出し、最後に <strong>Panels / Compare</strong> の切り替えです。比較ステージは 1 列のままで、各コマの言語が縦に並びます。<strong>言語</strong>チップ（JA / EN / ZH）で表示する言語を選びます（2 列を並べる幅がないためです）。ツールバーのグループは横スクロールで消えるのではなく次の行へ折り返し、ライブラリとノートは全画面のドロワーで開きます。</p><h2 id="タブレット縦向き-—-820-×-1180" tabindex="-1">タブレット縦向き — 820 × 1180 <a class="header-anchor" href="#タブレット縦向き-—-820-×-1180" aria-label="Permalink to &quot;タブレット縦向き — 820 × 1180&quot;">​</a></h2><figure class="shot"><img src="'+i+'" alt="820 × 1180 のタブレット画面：トップバーは 1 行、比較は幅いっぱいの 1 列"><figcaption>820 × 1180：トップバーは 1 行、サイドバーはドロワー、比較は 1 列のまま、ツールバーは 2 段。</figcaption></figure><p>820 px ではトップバーが 1 行に戻り、サイドバーはドロワーのままですが、比較ステージは依然として 1 列で、言語ペインは横に並ばず縦に積まれます。<strong>言語</strong>チップの使い方はスマートフォンと同じです。ツールバーは 2 段に分かれ、上段が言語と表示の操作、下段が注釈ツールです。ノートはステージの上にドロワーで開きます。</p><h2 id="タブレット横向き-—-1180-×-820" tabindex="-1">タブレット横向き — 1180 × 820 <a class="header-anchor" href="#タブレット横向き-—-1180-×-820" aria-label="Permalink to &quot;タブレット横向き — 1180 × 820&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="1180 × 820 のタブレット画面：サイドバーが開き、3 言語のペインが横に並ぶ"><figcaption>1180 × 820：サイドバーが開き、3 言語が横並び、ノートはドロワー。</figcaption></figure><p>1180 px ではサイドバー（240 px）が戻り、3 言語のペインが横 1 列に並びます（各約 290 px）。この幅でもノートはドロワーで、開くとステージの上に重なります。ツールバーは 2 段のままで、上段が言語と位置合わせ、下段が注釈ツールです。<strong>Export HTML</strong> はトップバーに残ります。</p><div class="tip custom-block"><p class="custom-block-title">自分で撮るときは</p><p>ページのズームではなくブラウザのウィンドウを直接リサイズしてください。ブレークポイントはビューポート幅を見ており、サイドバーとノート列はウィンドウ自体がブレークポイントを越えたときだけ入れ替わります。</p></div>',18)])])}const P=s(l,[["render",d]]);export{b as __pageData,P as default};
